#!/usr/bin/env bash
# Regenerate every checked-in generated client from its source contract.
#
#   scripts/regenerate.sh                    rewrite every file in place
#   scripts/regenerate.sh --check            regenerate into a scratch dir and fail on drift
#   scripts/regenerate.sh [--check] showcase ts2py   only the named targets
#
# Targets: skill quickstart showcase router py2ts best-practice ts2py
#
# Generated files carry a "Generated by MeshCall" header and are never edited by
# hand; this script (and the CI "drift" job) is the only way they change.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT=$PWD
MODE=write
if [ "${1:-}" = "--check" ]; then MODE=--check; shift; fi
TARGETS=${*:-skill quickstart showcase router py2ts best-practice ts2py}
wanted() { case " $TARGETS " in *" $1 "*) return 0 ;; *) return 1 ;; esac; }
SCRATCH=$(mktemp -d)
trap 'rm -rf "$SCRATCH"' EXIT
status=0
export NODE_OPTIONS="${NODE_OPTIONS:-} --no-deprecation"

py() { (cd "$1" && shift && uv run --locked --reinstall-package meshcall "$@"); }

# Python formatting is applied to generated Python so that output is stable
# regardless of the generator's own line wrapping.
format_py() { (cd meshcall-py && uv run --locked ruff format --quiet "$@" && uv run --locked ruff check --quiet --fix --select I "$@" >/dev/null || true); }

compare() { # compare <generated-path> <checked-in-path>
  if [ "$MODE" = "--check" ]; then
    if ! diff -u "$2" "$1" >/dev/null; then
      echo "DRIFT: $2 differs from what the generator produces" >&2
      diff -u "$2" "$1" | head -40 >&2 || true
      status=1
    else
      echo "ok   $2"
    fi
  else
    cp "$1" "$2" && echo "wrote $2"
  fi
}

# --- the first-party skill, embedded by each CLI ----------------------------
# skills/meshcall/SKILL.md is the source; `meshcall init` in Go, Python and
# TypeScript ships a copy (no header: the frontmatter must stay on line 1).
if wanted skill; then
  for copy in meshcall-router/internal/skill/SKILL.md meshcall-py/src/meshcall/skills/meshcall/SKILL.md meshcall-ts/skills/meshcall/SKILL.md; do
    compare skills/meshcall/SKILL.md "$copy"
  done
fi

# --- single-file Python clients generated from Python services -------------
single_file() { # single_file <target> <demo-dir> <module:Class> <relative output>
  wanted "$1" || return 0
  local dir=$2 spec=$3 out=$4
  # Assigned separately: `local a=$1 b="$(f "$a")"` expands $a before it is set.
  local tmp="$SCRATCH/$(basename "$dir").py"
  py "$dir" meshcall generate "$spec" --single-file --output "$tmp"
  format_py "$tmp"
  compare "$tmp" "$dir/$out"
}
single_file quickstart demo/quickstart quickstart_demo.service:CounterService src/quickstart_demo/generated_client.py
single_file showcase demo/showcase showcase_demo.service:ShowcaseService src/showcase_demo/generated_client.py
single_file router demo/router router_demo.service:CounterService src/router_demo/generated_client.py

# --- TypeScript packages generated from Python services ---------------------
ts_package() { # ts_package <target> <dir> <module:Class> <package-name> <runtime-version> <output-dir>
  wanted "$1" || return 0
  local dir=$2 spec=$3 name=$4 runtime=$5 out=$6
  local tmp="$SCRATCH/$(basename "$dir")-ts"
  py "$dir" meshcall generate "$spec" --language typescript --runtime-version "$runtime" --package-name "$name" --output "$tmp"
  for f in client.ts models.ts index.ts; do compare "$tmp/src/$f" "$dir/$out/src/$f"; done
}
ts_package py2ts demo/py2ts py2ts_demo.service:PythonGreetingService meshcall-demo-py2ts-client file:../../../meshcall-ts ts-client
ts_package best-practice best-practice best_practice.service:LlmService meshcall-best-practice-client file:../../meshcall-ts ts-client

# --- Python package generated from a TypeScript service's contract ----------
if wanted ts2py; then
(cd meshcall-ts && yarn -s install --frozen-lockfile && yarn -s build) >/dev/null
# yarn keeps a stale copy of a file: dependency whose version did not change;
# drop it so the contract is exported with the current runtime.
(cd demo/ts2py/ts-server && rm -rf node_modules/meshcall && yarn -s install --frozen-lockfile --check-files >/dev/null && yarn -s run export-contract >/dev/null)
tmp="$SCRATCH/ts2py-py"
py demo/ts2py meshcall generate-contract ts-server/service.meshcall.json --language python --package-name meshcall-demo-ts2py-client --output "$tmp"
format_py "$tmp"/src/meshcall_demo_ts2py_client/*.py
for f in client.py models.py; do compare "$tmp/src/meshcall_demo_ts2py_client/$f" "demo/ts2py/py-client/src/meshcall_demo_ts2py_client/$f"; done
fi

exit $status
